class Solution {public:long long solve(vector<vector<int>> rectangles){set<int> edges;for(auto r:rectangles){edges.insert(r[0]);edges.insert(r[2]);}vector<int> xs(edges.begin(),edges.end());long long total=0;for(int i=1;i<(int)xs.size();i++){vector<pair<int,int>> intervals;for(auto r:rectangles)if(r[0]<=xs[i-1]&&r[2]>=xs[i])intervals.push_back({r[1],r[3]});sort(intervals.begin(),intervals.end());long long height=0,end=LLONG_MIN;for(auto p:intervals){if(p.second<=end)continue;height+=1LL*p.second-max(1LL*p.first,end);end=p.second;}total+=(1LL*xs[i]-xs[i-1])*height;}return total;}};